import java.net.*;import java.io.*;import java.util.*;
public class Smoke {
 static class C implements AutoCloseable {Socket s;DataInputStream in;DataOutputStream out;C()throws Exception{s=new Socket("127.0.0.1",5058);s.setSoTimeout(4000);in=new DataInputStream(s.getInputStream());out=new DataOutputStream(s.getOutputStream());}void send(String... a)throws Exception{out.writeInt(a.length);for(String x:a)out.writeUTF(x);out.flush();}String[] event(String type)throws Exception{for(int j=0;j<15;j++){int n=in.readInt();String[] a=new String[n];for(int i=0;i<n;i++)a[i]=in.readUTF();if(a[0].equals(type))return a;}throw new Exception("Missing "+type);}public void close()throws Exception{s.close();}}
 public static void main(String[] args)throws Exception{try(C a=new C();C b=new C()){a.send("REGISTER","alice","testpass");a.event("INFO");b.send("REGISTER","bob","testpass");b.event("INFO");a.send("LOGIN","alice","testpass");a.event("WELCOME");b.send("LOGIN","bob","testpass");b.event("WELCOME");a.send("CHALLENGE","bob","Mạng máy tính","Dễ");b.event("INVITE");b.send("ACCEPT","alice");String[] x=a.event("MATCH"),y=b.event("MATCH");if(!x[1].equals(y[1])||!x[6].equals(y[6])||x.length!=58)throw new AssertionError("Different questions");String[] submission=new String[12];submission[0]="SUBMIT";submission[1]=x[1];Arrays.fill(submission,2,12,"0");a.send(submission);b.send(submission);a.event("RESULT");b.event("RESULT");a.send("LEADERBOARD");a.event("LEADERBOARD");a.send("HISTORY");a.event("HISTORY");System.out.println("PASS 2 clients, same set, submit, result, leaderboard, history");}}
}
